class MyQueue {
    private final Deque<Integer> inbox = new ArrayDeque<>();

    public void enqueue(int x) {
        inbox.push(x);
    }

    public int dequeue() {
        Deque<Integer> temp = new ArrayDeque<>();
        while (!inbox.isEmpty()) temp.push(inbox.pop());
        int front = temp.pop();
        while (!temp.isEmpty()) inbox.push(temp.pop());
        return front;
    }

    public boolean empty() {
        return inbox.isEmpty();
    }
}

